int status_code = 99; // Global definition

namespace System {
    int status_code = 1; // Localized definition
}

void resolve_scope() {
    int local = System::status_code; // 1
    int global = ::status_code;      // 99
}

// --- Global Access in Nested Scopes ---

int BUFFER_SIZE = 100;

namespace Network {
    namespace Config {
        int BUFFER_SIZE = 200; // Nested shadow

        void log_size() {
            int current = BUFFER_SIZE;    // Config::BUFFER_SIZE (200)
            int root = ::BUFFER_SIZE;     // Global (100)
        }
    }
}
